import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.Ch4PdLd_.js";const k=JSON.parse('{"title":"nekcode 是什么","description":"","frontmatter":{},"headers":[],"relativePath":"start/introduction.md","filePath":"start/introduction.md"}'),n={name:"start/introduction.md"};function r(i,e,c,s,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="nekcode-是什么" tabindex="-1">nekcode 是什么 <a class="header-anchor" href="#nekcode-是什么" aria-label="Permalink to &quot;nekcode 是什么&quot;">​</a></h1><p>nekcode（命令名 <code>nek</code>）是一个运行在终端里的编程助手。你在项目目录里启动它，用自然语言描述任务，它会调用工具读文件、搜索代码、执行命令、修改文件，并把每一步都显示出来。</p><p>nekcode 基于开源项目 <a href="https://github.com/earendil-works/pi" target="_blank" rel="noreferrer">pi</a> 二次开发，保留了 pi 的会话、模型、扩展等全部基础能力，并在此之上增加了一组面向“规划 + 分工”的功能。</p><h2 id="和-pi-相比多了什么" tabindex="-1">和 pi 相比多了什么 <a class="header-anchor" href="#和-pi-相比多了什么" aria-label="Permalink to &quot;和 pi 相比多了什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>说明</th><th>详见</th></tr></thead><tbody><tr><td>Plan 模式</td><td>先调研、写计划，审阅通过后再实施；计划保存在 <code>.nek/plans/</code></td><td><a href="/nekcode/guide/plan-mode">Plan 模式</a></td></tr><tr><td>Todo 列表</td><td>多步任务的进度显示在输入框上方</td><td><a href="/nekcode/guide/todos">Todo 列表</a></td></tr><tr><td>子代理</td><td>把边界清晰的任务派给独立子会话，可前台或后台运行</td><td><a href="/nekcode/guide/subagents">子代理</a></td></tr><tr><td>新的文件工具</td><td>Cursor 风格的分块 <code>read</code>、Claude Code 风格的精确替换 <code>edit</code>、结构化搜索 <code>ast_grep</code></td><td><a href="/nekcode/guide/tools">内置工具</a></td></tr><tr><td><code>ask_question</code></td><td>模型需要你做决定时，弹出多选题而不是长篇追问</td><td><a href="/nekcode/guide/tools#ask-question">内置工具</a></td></tr><tr><td><code>web_search</code></td><td>联网搜索，无需 API key</td><td><a href="/nekcode/guide/tools#web-search">内置工具</a></td></tr><tr><td>MCP</td><td>内置 MCP 客户端和按需加载工具的 <code>tool_search</code></td><td><a href="/nekcode/guide/mcp">MCP 服务器</a></td></tr><tr><td>崩溃后续跑</td><td>每一步写入 SQLite，进程被杀后 <code>nek -c</code> 接着跑</td><td><a href="/nekcode/reference/durable-sessions">Durable 会话</a></td></tr><tr><td>一键安装与更新</td><td>从源码运行，<code>nek update</code> 跟随 stable 或 dev 通道</td><td><a href="/nekcode/start/install">安装、更新与卸载</a></td></tr><tr><td>OpenTUI 界面</td><td>实验性的新终端界面，<code>nek --ui opentui</code></td><td><a href="/nekcode/guide/opentui">OpenTUI 界面</a></td></tr></tbody></table><h2 id="和-pi-的区别" tabindex="-1">和 pi 的区别 <a class="header-anchor" href="#和-pi-的区别" aria-label="Permalink to &quot;和 pi 的区别&quot;">​</a></h2><p>如果你用过 pi，需要注意这些差异：</p><ul><li><strong>命令和目录不同</strong>：命令是 <code>nek</code>，用户配置在 <code>~/.nek/agent/</code>，项目配置在 <code>.nek/</code>。nek 不会读取或迁移 <code>~/.pi/</code> 里的数据。</li><li><strong>不通过 npm 安装</strong>：npm 上的 <code>@earendil-works/pi-coding-agent</code> 是上游 pi，装出来的是 <code>pi</code> 命令。nek 用安装脚本从源码安装，见 <a href="/nekcode/start/install">安装</a>。</li><li><strong>没有包管理命令</strong>：pi 的 <code>install</code>、<code>remove</code>、<code>list</code>、<code>config</code> 等包管理命令已移除。<code>nek update</code> 用来更新 nek 自己。扩展用 <code>-e</code> 加载或放进扩展目录，见 <a href="/nekcode/customize/loading-extensions">加载扩展</a>。</li><li><strong>默认工具更多</strong>：新会话默认启用 <code>read</code>、<code>bash</code>、<code>edit</code>、<code>write</code>、<code>grep</code>、<code>find</code>、<code>ls</code>、<code>ast_grep</code>、<code>web_search</code>，以及 nek 自带的 Plan、Todo、子代理等工具。</li><li><strong>默认全屏界面</strong>：对话记录由 nek 自己滚动。想用终端原生的滚动条，用 <code>--tui-mode regular</code>。</li></ul><h2 id="版本号" tabindex="-1">版本号 <a class="header-anchor" href="#版本号" aria-label="Permalink to &quot;版本号&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nek</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># nek 0.3.0 (pi 1.0.2)</span></span></code></pre></div><p>前面是 nek 自己的版本，括号里是它所基于的 pi 版本。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/nekcode/start/install">安装 nek</a></li><li><a href="/nekcode/start/quickstart">快速上手：完成第一个任务</a></li><li><a href="/nekcode/start/how-it-works">了解 nek 的工作方式</a></li></ul>`,13)])])}const u=t(n,[["render",r]]);export{k as __pageData,u as default};
